String plain = sample.payload();
String stored = plain == null ? null : cipher.encrypt(plain);
String hash = sha256Hex(plain == null ? "" : plain);
TransactionalOperator tx = TransactionalOperator.create(new R2dbcTransactionManager(client.getConnectionFactory()));
DatabaseClient.GenericExecuteSpec base = client.sql("INSERT INTO telemetry_records (device_id, metric, t_device, t_ingress, sample_value, validation_status, payload_hash, payload) VALUES (:deviceId, :metric, :tDevice, :tIngress, :value, :status, :hash, :payload)")
        .bind("deviceId", sample.deviceId())
        .bind("metric", sample.metric())
        .bind("tDevice", utc(sample.tDevice()))
        .bind("tIngress", utc(sample.tIngress()))
        .bind("value", sample.value())
        .bind("status", sample.status().name())
        .bind("hash", hash);
DatabaseClient.GenericExecuteSpec spec = stored == null ? base.bindNull("payload", String.class) : base.bind("payload", stored);
Mono<Boolean> appended = spec
        .filter(statement -> statement.returnGeneratedValues("record_id"))
        .map(row -> row.get(0, Long.class))
        .one()
        .flatMap(recordId -> insertRevision(recordId, 1, sample.value(), "INITIAL"))
        .thenReturn(true);
return tx.transactional(appended)
        .onErrorResume(RuntimeException.class, error -> isUniqueViolation(error) ? Mono.just(false) : Mono.error(error));
